import type { IconProps } from './icons/props.ts'

/** Native viewBox of {@link FISH_LOGO_PATH} (width and height in user units). */
export const FISH_LOGO_VIEWBOX = { width: 23.16, height: 17.04 }

/** Swallow path data for consumers composing entrance effects or masks around the same geometry. */
export const FISH_LOGO_PATH = 'M1 16 7 12 4 7 10 10 8 0 17 8 21 7 23 8 21 9 18 14 13 16 7 17Z'

/**
 * Render the PureGamma Harness swallow mark.
 * @param props.size - width in px (default 24; height keeps the 23.16:17.04 ratio).
 * @param props.className - extra class for layout placement.
 * @returns the logo svg (aria-hidden; pair with the wordmark for accessibility).
 */
export function FishLogo({ size = 24, className }: IconProps) {
  return (
    <svg
      width={size}
      height={(size * FISH_LOGO_VIEWBOX.height) / FISH_LOGO_VIEWBOX.width}
      className={className}
      viewBox={`0 0 ${FISH_LOGO_VIEWBOX.width} ${FISH_LOGO_VIEWBOX.height}`}
      fill="none"
      aria-hidden="true"
    >
      <image href="data:image/png;base64," x="0" y="0" width="23.16" height="17.04" />
    </svg>
  )
}
